import{_ as a,o as s,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"设备信息-profile 绑定","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/features/device.md","filePath":"projects/lotus-plugin/docs/features/device.md"}'),n={name:"projects/lotus-plugin/docs/features/device.md"};function r(o,e,p,t,c,d){return s(),i("div",null,[...e[0]||(e[0]=[l(`<h1 id="设备信息-profile-绑定" tabindex="-1">设备信息-profile 绑定 <a class="header-anchor" href="#设备信息-profile-绑定" aria-label="Permalink to &quot;设备信息-profile 绑定&quot;">​</a></h1><p>返回：<a href="./../profile-login.html">上一级</a> / <a href="./../README.html">文档目录</a> / <a href="./README.html">小功能索引</a></p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><ul><li>每个 profile 独立保存设备信息，不会和其他 profile 共用或覆盖。</li><li>米游社社区签到、游戏签到 UA、绝区零更新面板等请求会自动使用对应 profile 的设备字段。</li><li>支持完整设备 JSON，也支持已有的 <code>device_id/device_fp</code>。</li><li>资料卡和设备信息页只展示脱敏内容。</li></ul><p>设备 ID 和 FP 必须来自同一设备；只有 FP、没有对应 ID 的新绑定会被拒绝。更换设备时，不沿用旧设备的名称、型号等信息。绑定保存后会同步既有上游绑定及设备缓存；同步失败保留待修复标记，后续重试同步，不重复兑换登录凭据。</p><p>荷花桥接的请求明确携带 profile 上下文。公共请求层还会处理 genshin、Miao 和 ZZZ 使用的米游社请求：核对实际 Cookie 所属账号，再选择对应的设备 ID、FP 和可用设备字段。共享 CK 使用实际 CK 所属账号的信息；同账号多个 profile 有不同设备时，不能仅凭账号 UID 选择第一个 profile。没有设备信息的 profile 自动生成并保存虚拟设备，后续请求复用其 ID、型号和系统信息；不在每次请求时重新随机。已有完整或部分设备信息保留，避免静默替换用户提供的身份。</p><p>请求、验证码创建、业务校验与重请求沿用同一设备上下文。<code>mys.req.err</code> 负责错误后的处理，不能替代发请求前的设备核对。Passport、米游社记录、社区、商城和云游戏按各自协议生成签名及请求字段，不将一套请求头套到全部接口。</p><h2 id="自动设备" tabindex="-1">自动设备 <a class="header-anchor" href="#自动设备" aria-label="Permalink to &quot;自动设备&quot;">​</a></h2><p>新 profile 创建时保存随机虚拟设备；旧档案在启动时补齐。型号、Android/API 版本、固件指纹、屏幕和容量从相容组合选取，当前覆盖 Pixel 6 至 Pixel 8 系列及 Android 12–14。完整固件指纹参考 <a href="https://developers.google.com/android/binary_transparency/image_info.txt" target="_blank" rel="noreferrer">Google 官方透明日志</a>，身份标识随机生成并固定保存。</p><p>FP 仅接受官方成功签发的结果。插件启动后延迟补全，使用已经保存的设备 ID；失败时保留原设备、不发送假 FP，并按退避间隔重试。已有 FP 的设备不重复申请。ID 与 FP 齐全后可运行已开启的社区任务；补全前仅跳过需要完整设备信息的任务。</p><p>绑定真机后覆盖自动设备信息。正在进行的后台签发会核对设备实例和登录状态，旧结果不能覆盖新绑定；自动生成不会更改签到开关。</p><h2 id="指令用法" tabindex="-1">指令用法 <a class="header-anchor" href="#指令用法" aria-label="Permalink to &quot;指令用法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#绑定设备[profile]</span></span>
<span class="line"><span>#绑定设备信息[profile] &lt;设备信息&gt;</span></span>
<span class="line"><span>#原神绑定设备[profile]</span></span>
<span class="line"><span>#星铁绑定设备[profile]</span></span>
<span class="line"><span>#绝区零绑定设备[profile]</span></span>
<span class="line"><span>#设备信息[profile]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="变量说明" tabindex="-1">变量说明 <a class="header-anchor" href="#变量说明" aria-label="Permalink to &quot;变量说明&quot;">​</a></h2><ul><li><code>profile</code>：可选，Lotus 内部 profile 序号，范围 <code>1..255</code>；省略时使用 profile 1。</li><li><code>设备信息</code>：可选，完整设备 JSON 或包含 <code>device_id/device_fp</code> 的文本。省略时按交互提示继续绑定。</li></ul>`,15)])])}const u=a(n,[["render",r]]);export{h as __pageData,u as default};
